   167  bool lwan_strbuf_append_str(struct lwan_strbuf *s1, const char *s2, size_t sz)
   168  {
   169      if (!sz)
   170          sz = strlen(s2);
   171
   172      if (UNLIKELY(!grow_buffer_if_needed(s1, s1->used + sz + 2)))
   173          return false;
   174
   175      memcpy(s1->value.buffer + s1->used, s2, sz);
   176      s1->used += sz;
   177      s1->value.buffer[s1->used] = '\0';
